function fakeFetch() {
  return new Promise(resolve => setTimeout(() => resolve(Math.floor(Math.random() * 100)), 800));
}

function App() {
  const [value, setValue] = useState(null);
  const [loading, setLoading] = useState(true);
  useEffect(() => {
    let active = true;
    fakeFetch().then(n => {
      if (active) { setValue(n); setLoading(false); }
    });
    return () => { active = false; };
  }, []);
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <h2>Result: {loading ? 'Loading…' : value}</h2>
    </div>
  );
}

