function App() {
  const [userId, setUserId] = useState(1);
  const [data, setData] = useState(null);

  // BUG 1: [] means run once — userId is never re-read, value goes stale
  useEffect(() => {
    setData('loaded user ' + userId);
  }, []);

  // BUG 2: no dependency array + a state update => runs every render => infinite loop
  useEffect(() => {
    setData('refreshed ' + Date.now());
  });

  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <h2>{data}</h2>
      <button onClick={() => setUserId(id => id + 1)}>Next user (now {userId})</button>
    </div>
  );
}

solution.code:
function App() {
  const [userId, setUserId] = useState(1);
  const [data, setData] = useState(null);

  // Fixed: list userId so the effect re-runs whenever it changes
  useEffect(() => {
    setData('loaded user ' + userId);
  }, [userId]);

  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <h2>{data}</h2>
      <button onClick={() => setUserId(id => id + 1)}>Next user (now {userId})</button>
    </div>
  );
}

function App() {
  const [width, setWidth] = useState(window.innerWidth);
  useEffect(() => {
    const onResize = () => setWidth(window.innerWidth);
    window.addEventListener('resize', onResize);
    return () => window.removeEventListener('resize', onResize);
  }, []);
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <h2>Window width: {width}px</h2>
      <p>Resize the preview to see it update.</p>
    </div>
  );
}
